class LidarBox(Base):
    """
    Lidar box from tracker.
    """
    __tablename__ = 'lidar_box'
    token: str = Column(sql_types.HexLen8, primary_key=True)
    lidar_pc_token: str = Column(sql_types.HexLen8, ForeignKey('lidar_pc.token'), nullable=False)
    track_token: str = Column(sql_types.HexLen8, ForeignKey('track.token'))
    next_token = Column(sql_types.HexLen8, ForeignKey('lidar_box.token'), nullable=True)
    prev_token = Column(sql_types.HexLen8, ForeignKey('lidar_box.token'), nullable=True)
    x: float = Column(Float)
    y: float = Column(Float)
    z: float = Column(Float)
    width: float = Column(Float)
    length: float = Column(Float)
    height: float = Column(Float)
    vx: float = Column(Float)
    vy: float = Column(Float)
    vz: float = Column(Float)
    yaw: float = Column(Float)
    confidence: float = Column(Float)
    next = relationship('LidarBox', foreign_keys=[next_token], remote_side=[token])
    prev = relationship('LidarBox', foreign_keys=[prev_token], remote_side=[token])

    @property
    def _session(self) -> Any:
        """
        Get the underlying session.
        :return: The underlying session.
        """
        return inspect(self).session

    def __iter__(self) -> IterableLidarBox:
        """
        Returns a iterator object for LidarBox.
        :return: The iterator object.
        """
        return IterableLidarBox(self)

    def __reversed__(self) -> IterableLidarBox:
        """
        Returns a iterator object for LidarBox that traverses in reverse.
        :return: The iterator object.
        """
        return IterableLidarBox(self, reverse=True)

    def __repr__(self) -> str:
        """
        Return the string representation.
        :return: The string representation.
        """
        desc: str = simple_repr(self)
        return desc

    @property
    def log(self) -> Log:
        """
        Returns the Log containing the LidarBox.
        :return: The log containing the lidar box.
        """
        return self.lidar_pc.log

    @property
    def category(self) -> Category:
        """
        Returns the Category of the LidarBox.
        :return: The category of the lidar box.
        """
        return self.track.category

    @property
    def timestamp(self) -> int:
        """
        Returns the timestamp of the LidarBox.
        :return: The timestamp of the lidar box.
        """
        return int(self.lidar_pc.timestamp)

    @property
    def distance_to_ego(self) -> float:
        """
        Returns the distance of detection from Ego Vehicle.
        :return: The distance to ego vehicle.
        """
        return float(np.sqrt((self.x - self.lidar_pc.ego_pose.x) ** 2 + (self.y - self.lidar_pc.ego_pose.y) ** 2))

    @property
    def size(self) -> List[float]:
        """
        Get the box size.
        :return: The box size.
        """
        return [self.width, self.length, self.height]

    @property
    def translation(self) -> List[float]:
        """
        Get the box location.
        :return: The box location.
        """
        return [self.x, self.y, self.z]

    @property
    def rotation(self) -> List[float]:
        """
        Get the box rotation in euler angles.
        :return: The box rotation in euler angles.
        """
        qx = Quaternion(axis=(1, 0, 0), radians=0.0)
        qy = Quaternion(axis=(0, 1, 0), radians=0.0)
        qz = Quaternion(axis=(0, 0, 1), radians=self.yaw)
        return list(qx * qy * qz)

    @property
    def quaternion(self) -> Quaternion:
        """
        Get the box rotation in quaternion.
        :return: The box rotation in quaternion.
        """
        return Quaternion(self.rotation)

    @property
    def translation_np(self) -> npt.NDArray[np.float64]:
        """
        Get the box translation in numpy.
        :return: <np.float: 3> Translation.
        """
        return np.array(self.translation)

    @property
    def size_np(self) -> npt.NDArray[np.float64]:
        """
        Get the box size in numpy.
        :return: <np.float, 3> Width, length and height.
        """
        return np.array(self.size)

    @cached(cache=LRUCache(maxsize=LIDAR_BOX_LRU_CACHE_SIZE), key=lambda self: hashkey(self.track_token))
    def _get_box_items(self) -> Tuple[List[Integer], List[LidarBox]]:
        """
        Get all boxes along the track.
        :return: The list of timestamps and boxes along the track.
        """
        box_list: List[LidarBox] = self._session.query(LidarBox).filter(LidarBox.track_token == self.track_token).all()
        sorted_box_list = sorted(box_list, key=lambda x: x.timestamp)
        return ([b.timestamp for b in sorted_box_list], sorted_box_list)

    @cached(cache=LRUCache(maxsize=LIDAR_BOX_LRU_CACHE_SIZE), key=lambda self: hashkey(self.track_token))
    def get_box_items_to_iterate(self) -> Dict[int, Tuple[Optional[LidarBox], Optional[LidarBox]]]:
        """
        Get all boxes along the track.
        :return: Dict. Key is timestamp of box, value is Tuple of (prev,next) LidarBox.
        """
        box_list = self._session.query(LidarBox).filter(LidarBox.track_token == self.track_token).all()
        sorted_box_list = sorted(box_list, key=lambda x: x.timestamp)
        return {box.timestamp: (prev, next) for box, prev, next in zip(sorted_box_list, [None] + sorted_box_list[:-1], sorted_box_list[1:] + [None])}

    def _find_box(self, step: int=0) -> Optional[LidarBox]:
        """
        Find the next box along the track with the given step.
        :param: step: The number of steps to look ahead, defaults to zero.
        :return: The found box if any.
        """
        timestamp_list, sorted_box_list = self._get_box_items()
        i = bisect.bisect_left(timestamp_list, self.timestamp)
        j = i + step
        if j < 0 or j >= len(sorted_box_list):
            return None
        return sorted_box_list[j]

    def future_or_past_ego_poses(self, number: int, mode: str, direction: str) -> List[EgoPose]:
        """
        Get n future or past vehicle poses. Note here the frequency of pose differs from frequency of LidarBox.
        :param number: Number of poses to fetch or number of seconds of ego poses to fetch.
        :param mode: Either n_poses or n_seconds.
        :param direction: Future or past ego poses to fetch, could be 'prev' or 'next'.
        :return: List of up to n or n seconds future or past ego poses.
        """
        if direction == 'prev':
            if mode == 'n_poses':
                return self._session.query(EgoPose).filter(EgoPose.timestamp < self.lidar_pc.ego_pose.timestamp, self.lidar_pc.lidar.log_token == EgoPose.log_token).order_by(EgoPose.timestamp.desc()).limit(number).all()
            elif mode == 'n_seconds':
                return self._session.query(EgoPose).filter(EgoPose.timestamp - self.lidar_pc.ego_pose.timestamp < 0, EgoPose.timestamp - self.lidar_pc.ego_pose.timestamp >= -number * 1000000.0, self.lidar_pc.lidar.log_token == EgoPose.log_token).order_by(EgoPose.timestamp.desc()).all()
            else:
                raise ValueError(f'Unknown mode: {mode}.')
        elif direction == 'next':
            if mode == 'n_poses':
                return self._session.query(EgoPose).filter(EgoPose.timestamp > self.lidar_pc.ego_pose.timestamp, self.lidar_pc.lidar.log_token == EgoPose.log_token).order_by(EgoPose.timestamp.asc()).limit(number).all()
            elif mode == 'n_seconds':
                return self._session.query(EgoPose).filter(EgoPose.timestamp - self.lidar_pc.ego_pose.timestamp > 0, EgoPose.timestamp - self.lidar_pc.ego_pose.timestamp <= number * 1000000.0, self.lidar_pc.lidar.log_token == EgoPose.log_token).order_by(EgoPose.timestamp.asc()).all()
            else:
                raise ValueError(f'Unknown mode: {mode}.')
        else:
            raise ValueError(f'Unknown direction: {direction}.')

    def _temporal_neighbors(self) -> Tuple[LidarBox, LidarBox, bool, bool]:
        """
        Find temporal neighbors to calculate velocity and angular velocity.
        :return: The previous box, next box and their existences. If the previous or next box do not exist, they will
            be set to the current box itself.
        """
        has_prev = self.prev is not None
        has_next = self.next is not None
        if has_prev:
            prev_lidar_box = self.prev
        else:
            prev_lidar_box = self
        if has_next:
            next_lidar_box = self.next
        else:
            next_lidar_box = self
        return (prev_lidar_box, next_lidar_box, has_prev, has_next)

    @property
    def velocity(self) -> npt.NDArray[np.float64]:
        """
        Estimate box velocity for a box.
        :return: The estimated box velocity of the box.
        """
        max_time_diff = 1.5
        prev_lidar_box, next_lidar_box, has_prev, has_next = self._temporal_neighbors()
        if not has_prev and (not has_next):
            return np.array([np.nan, np.nan, np.nan])
        pos_next: npt.NDArray[np.float64] = np.array(next_lidar_box.translation)
        pos_prev: npt.NDArray[np.float64] = np.array(prev_lidar_box.translation)
        pos_diff: npt.NDArray[np.float64] = pos_next - pos_prev
        pos_diff[2] = 0
        time_next = 1e-06 * next_lidar_box.timestamp
        time_prev = 1e-06 * prev_lidar_box.timestamp
        time_diff = time_next - time_prev
        if has_next and has_prev:
            max_time_diff *= 2
        if time_diff > max_time_diff:
            return np.array([np.nan, np.nan, np.nan])
        else:
            return pos_diff / time_diff

    @property
    def angular_velocity(self) -> float:
        """
        Estimate box angular velocity for a box.
        :return: The estimated box angular velocity of the box.
        """
        max_time_diff = 1.5
        prev_lidar_box, next_lidar_box, has_prev, has_next = self._temporal_neighbors()
        if not has_prev and (not has_next):
            return np.nan
        time_next = 1e-06 * next_lidar_box.timestamp
        time_prev = 1e-06 * prev_lidar_box.timestamp
        time_diff = time_next - time_prev
        if has_next and has_prev:
            max_time_diff *= 2
        if time_diff > max_time_diff:
            return np.nan
        else:
            yaw_diff = next_lidar_box.yaw - prev_lidar_box.yaw
            if yaw_diff > np.pi:
                yaw_diff -= 2 * np.pi
            elif yaw_diff < -np.pi:
                yaw_diff += 2 * np.pi
            return float(yaw_diff / time_diff)

    def box(self) -> Box3D:
        """
        Get the Box3D representation of the box.
        :return: The box3d representation of the box.
        """
        label_local = raw_mapping['global2local'][self.category.name]
        label_int = raw_mapping['local2id'][label_local]
        return Box3D(center=self.translation, size=self.size, orientation=self.quaternion, token=self.token, label=label_int, track_token=self.track_token)

    def tracked_object(self, future_waypoints: Optional[List[Waypoint]]) -> TrackedObject:
        """
        Creates an Agent object
        :param future_waypoints: Optional future poses, which will be used as predicted trajectory
        """
        pose = StateSE2(self.translation[0], self.translation[1], self.yaw)
        oriented_box = OrientedBox(pose, width=self.size[0], length=self.size[1], height=self.size[2])
        label_local = raw_mapping['global2local'][self.category.name]
        tracked_object_type = TrackedObjectType[local2agent_type[label_local]]
        if tracked_object_type in AGENT_TYPES:
            return Agent(tracked_object_type=tracked_object_type, oriented_box=oriented_box, velocity=StateVector2D(self.vx, self.vy), predictions=[PredictedTrajectory(1.0, future_waypoints)] if future_waypoints else [], angular_velocity=np.nan, metadata=SceneObjectMetadata(token=self.token, track_token=self.track_token, track_id=None, timestamp_us=self.timestamp, category_name=self.category.name))
        else:
            return StaticObject(tracked_object_type=tracked_object_type, oriented_box=oriented_box, metadata=SceneObjectMetadata(token=self.token, track_token=self.track_token, track_id=None, timestamp_us=self.timestamp, category_name=self.category.name))

@property
def rotation(self) -> List[float]:
    """
        Get the box rotation in euler angles.
        :return: The box rotation in euler angles.
        """
    qx = Quaternion(axis=(1, 0, 0), radians=0.0)
    qy = Quaternion(axis=(0, 1, 0), radians=0.0)
    qz = Quaternion(axis=(0, 0, 1), radians=self.yaw)
    return list(qx * qy * qz)

def _find_box(self, step: int=0) -> Optional[LidarBox]:
    """
        Find the next box along the track with the given step.
        :param: step: The number of steps to look ahead, defaults to zero.
        :return: The found box if any.
        """
    timestamp_list, sorted_box_list = self._get_box_items()
    i = bisect.bisect_left(timestamp_list, self.timestamp)
    j = i + step
    if j < 0 or j >= len(sorted_box_list):
        return None
    return sorted_box_list[j]

@property
def velocity(self) -> npt.NDArray[np.float64]:
    """
        Estimate box velocity for a box.
        :return: The estimated box velocity of the box.
        """
    max_time_diff = 1.5
    prev_lidar_box, next_lidar_box, has_prev, has_next = self._temporal_neighbors()
    if not has_prev and (not has_next):
        return np.array([np.nan, np.nan, np.nan])
    pos_next: npt.NDArray[np.float64] = np.array(next_lidar_box.translation)
    pos_prev: npt.NDArray[np.float64] = np.array(prev_lidar_box.translation)
    pos_diff: npt.NDArray[np.float64] = pos_next - pos_prev
    pos_diff[2] = 0
    time_next = 1e-06 * next_lidar_box.timestamp
    time_prev = 1e-06 * prev_lidar_box.timestamp
    time_diff = time_next - time_prev
    if has_next and has_prev:
        max_time_diff *= 2
    if time_diff > max_time_diff:
        return np.array([np.nan, np.nan, np.nan])
    else:
        return pos_diff / time_diff

@property
def angular_velocity(self) -> float:
    """
        Estimate box angular velocity for a box.
        :return: The estimated box angular velocity of the box.
        """
    max_time_diff = 1.5
    prev_lidar_box, next_lidar_box, has_prev, has_next = self._temporal_neighbors()
    if not has_prev and (not has_next):
        return np.nan
    time_next = 1e-06 * next_lidar_box.timestamp
    time_prev = 1e-06 * prev_lidar_box.timestamp
    time_diff = time_next - time_prev
    if has_next and has_prev:
        max_time_diff *= 2
    if time_diff > max_time_diff:
        return np.nan
    else:
        yaw_diff = next_lidar_box.yaw - prev_lidar_box.yaw
        if yaw_diff > np.pi:
            yaw_diff -= 2 * np.pi
        elif yaw_diff < -np.pi:
            yaw_diff += 2 * np.pi
        return float(yaw_diff / time_diff)

def generate_multi_scale_connections(connections: npt.NDArray[np.float64], scales: List[int]) -> Dict[int, npt.NDArray[np.float64]]:
    """
    Generate multi-scale connections by finding the neighors up to max(scales) hops away for each node.

    :param connections: <np.float: num_connections, 2>. 1-hop connections.
    :param scales: Connections scales to generate.
    :return: Multi-scale connections as a dict of {scale: connections_of_scale}.
    """
    node_idx_to_neighbor_dict: Dict[int, Dict[str, Set[int]]] = {}
    for connection in connections:
        start_idx, end_idx = list(connection)
        if start_idx not in node_idx_to_neighbor_dict:
            node_idx_to_neighbor_dict[start_idx] = {'1_hop_neighbors': set()}
        if end_idx not in node_idx_to_neighbor_dict:
            node_idx_to_neighbor_dict[end_idx] = {'1_hop_neighbors': set()}
        node_idx_to_neighbor_dict[start_idx]['1_hop_neighbors'].add(end_idx)
    for scale in range(2, max(scales) + 1):
        for neighbor_dict in node_idx_to_neighbor_dict.values():
            neighbor_dict[f'{scale}_hop_neighbors'] = set()
            for n_hop_neighbor in neighbor_dict[f'{scale - 1}_hop_neighbors']:
                for n_plus_1_hop_neighbor in node_idx_to_neighbor_dict[n_hop_neighbor]['1_hop_neighbors']:
                    neighbor_dict[f'{scale}_hop_neighbors'].add(n_plus_1_hop_neighbor)
    multi_scale_connections: Dict[int, npt.NDArray[np.float64]] = {}
    for scale in scales:
        scale_connections = []
        for node_idx, neighbor_dict in node_idx_to_neighbor_dict.items():
            for n_hop_neighbor in neighbor_dict[f'{scale}_hop_neighbors']:
                scale_connections.append([node_idx, n_hop_neighbor])
        multi_scale_connections[scale] = np.array(scale_connections)
    return multi_scale_connections

def get_boxes(sample_data: Union[LidarPc, Image], frame: Frame=Frame.GLOBAL, trans_matrix_ego: Optional[npt.NDArray[np.float64]]=None, trans_matrix_sensor: Optional[npt.NDArray[np.float64]]=None) -> List[Box3D]:
    """
    Given a LidarPc/Image record, this function returns a list of boxes (in the global coordinate frame by
    default) associated with that record. It simply converts the annotations to boxes.
    :param sample_data: Either a Lidar pointcloud or an Image.
        Note: Having the type Union[LidarPc, Image] for this throws error for TRT with Python 3.8.
    :param frame: An enumeration of Frame (global/vehicle/sensor).
    :param trans_matrix_ego:
        Transformation matrix to transform the boxes from the global frame to the ego-vehicle frame.
    :param trans_matrix_sensor:
        Transformation matrix to transform the boxes from the ego-vehicle frame to the sensor frame.
    :return: List of boxes in the global coordinate frame.
    """
    if frame == Frame.VEHICLE:
        assert trans_matrix_ego is not None
    if frame == Frame.SENSOR:
        assert trans_matrix_ego is not None
        assert trans_matrix_sensor is not None
    boxes = [sa.box() for sa in sample_data.lidar_boxes]
    if frame in [Frame.VEHICLE, Frame.SENSOR]:
        for box in boxes:
            box.transform(trans_matrix_ego)
    if frame == Frame.SENSOR:
        for box in boxes:
            box.transform(trans_matrix_sensor)
    return boxes

def add_future_boxes(tracks_dict: Dict[str, List[Box3D]], lidar_pcs: List[LidarPc]) -> Dict[str, List[Box3D]]:
    """
    Iterate over future samples, adding boxes to the box sequence associated with each track token
    :param tracks_dict: Dictionary of boxes associated with track tokens.
    :param lidar_pcs: List of LidarPc.
    :return: Updated Dictionary that includes future boxes.
    """
    for idx, next_lidar_pc in enumerate(lidar_pcs[1:]):
        next_lidar_boxes = next_lidar_pc.lidar_boxes
        for lidar_box in next_lidar_boxes:
            track_token = lidar_box.track_token
            if track_token not in tracks_dict:
                continue
            tracks_dict[track_token].append(lidar_box.box())
        for track_token, track in tracks_dict.items():
            if len(track) < idx + 1:
                tracks_dict[track_token].append(None)
    return tracks_dict

def get_future_box_sequence(lidar_pcs: List[LidarPc], frame: Frame, future_horizon_len_s: float, future_interval_s: float, extrapolation_threshold_ms: float=100000.0, trans_matrix_ego: Optional[npt.NDArray[np.float64]]=None, trans_matrix_sensor: Optional[npt.NDArray[np.float64]]=None) -> Dict[str, List[Box3D]]:
    """
    Get a mapping from track token to box sequence over time for each box in the input data. Box
    annotations are sampled at a frequency of 20Hz.
    :param lidar_pcs: List of LidarPc.
    :param frame: An enumeration of Frame (global/vehicle/sensor).
    :param future_horizon_len_s: Timestamp horizon of the future waypoints in seconds.
    :param future_interval_s: Timestamp interval of the future waypoints in seconds.
    :param extrapolation_threshold_ms: If a target interpolation timestamp extends beyond the timestamp of the
        last recorded bounding box for an actor, then the values for the box position at the target timestamp will only
        be extrapolated if the target timestamp is within the specified number of microseconds of the last recorded
        bounding box. Otherwise the box at the target timestamp will be set to None.
    :param trans_matrix_ego:
        Transformation matrix to transform the boxes from the global frame to the ego-vehicle frame.
    :param trans_matrix_sensor:
        Transformation matrix to transform the boxes from the ego-vehicle frame to the sensor frame.
    :return: Mapping from track token to list of corresponding boxes at each timestamp in the global coordinate
        frame, where the first box corresponds to the current timestamp t0.
    """
    if frame == Frame.VEHICLE:
        assert trans_matrix_ego is not None
    if frame == Frame.SENSOR:
        assert trans_matrix_ego is not None
        assert trans_matrix_sensor is not None
    num_future_boxes = int(future_horizon_len_s / future_interval_s)
    num_target_timestamps = num_future_boxes + 1
    future_horizon_len_ms = future_horizon_len_s * 1000000.0
    start_timestamp = lidar_pcs[0].timestamp
    tracks_dict = {lidar_box.track_token: [lidar_box.box()] for lidar_box in lidar_pcs[0].lidar_boxes}
    timestamps = [lidar_pc.timestamp for lidar_pc in lidar_pcs]
    tracks_dict = add_future_boxes(tracks_dict, lidar_pcs)
    target_timestamps: Union[npt.NDArray[np.float64], List[float]] = np.linspace(start=start_timestamp, stop=start_timestamp + future_horizon_len_ms, num=num_target_timestamps)
    for track_token, track in tracks_dict.items():
        last_box_index = get_last_box_index(box_sequence=track)
        if last_box_index == 0:
            tracks_dict[track_token] = [track[0]] + [None] * num_future_boxes
            continue
        last_box_timestamp = timestamps[last_box_index]
        target_timestamps = [t for t in target_timestamps if t <= last_box_timestamp + extrapolation_threshold_ms]
        box_indices = [i for i, box in enumerate(track) if box is not None]
        interpolated_boxes: List[Optional[Box3D]] = []
        interpolated_boxes.extend(interpolate_boxes(target_timestamps=target_timestamps, timestamps=np.array([float(timestamps[i]) for i in box_indices]), box_sequence=[track[i] for i in box_indices]))
        if frame in [Frame.VEHICLE, Frame.SENSOR]:
            for box in interpolated_boxes:
                if box is not None:
                    box.transform(trans_matrix_ego)
        if frame == Frame.SENSOR:
            for box in interpolated_boxes:
                if box is not None:
                    box.transform(trans_matrix_sensor)
        num_missing_final_boxes = num_target_timestamps - len(interpolated_boxes)
        if num_missing_final_boxes:
            interpolated_boxes.extend([None] * num_missing_final_boxes)
        tracks_dict[track_token] = interpolated_boxes
    return tracks_dict

def interpolate_boxes(target_timestamps: Union[npt.NDArray[np.float64], List[float]], timestamps: Union[npt.NDArray[np.float64], List[float]], box_sequence: List[Box3D]) -> List[Box3D]:
    """
    Given a sequence of boxes representing box positions over time along with their corresponding timestamps,
    interpolate the box center, rotation, velocity and angular velocity at the target timestamps. Target timestamps
    should lie within the range of the raw timestamps corresponding to recorded data.
    :param target_timestamps: Times at which box values will be interpolated, sorted in increasing order.
    :param timestamps: Times corresponding to each box in the box sequence, sorted in increasing order.
    :param box_sequence: Sequence of boxes at each timestamp corresponding to an actor's position over time, from the
        raw data. The first box corresponds to the current frame.
    :return: Sequence of boxes at each timestamp corresponding to an actor's position over time, where box center,
        rotation, velocity and angular velocity are interpolated at the target timestamps.
    """
    assert len(timestamps) == len(box_sequence)
    if sorted(list(timestamps)) != list(timestamps) or sorted(list(target_timestamps)) != list(target_timestamps):
        raise ValueError(f'Check input. Timestamps should be sorted, but received the following inputs:\ntimestamps: {list(timestamps)}\ntarget_timestamps: {target_timestamps}')
    centers = interpolate_coordinates(box_timestamps=timestamps, box_coordinates=[box.center for box in box_sequence], target_timestamps=target_timestamps)
    rotations = interpolate_rotations(boxes=box_sequence, box_timestamps=list(timestamps), target_timestamps=list(target_timestamps))
    velocities = interpolate_coordinates(box_timestamps=timestamps, box_coordinates=[box.velocity for box in box_sequence], target_timestamps=target_timestamps)
    angular_velocities = np.interp(x=target_timestamps, xp=timestamps, fp=np.array([box.angular_velocity for box in box_sequence]))
    first_box = box_sequence[0]
    interpolated_boxes = []
    for c, r, v, w in zip(centers, rotations, velocities, angular_velocities):
        next_box = first_box.copy()
        next_box.center, next_box.orientation, next_box.velocity, next_box.angular_velocity = (c, r, v, w)
        interpolated_boxes.append(next_box)
    return interpolated_boxes

def interpolate_rotations(boxes: List[Box3D], box_timestamps: List[float], target_timestamps: List[float]) -> List[Quaternion]:
    """
    Given a sequence of boxes representing box positions over time along with their corresponding timestamps,
    interpolate the box rotation at the target timestamps. Target timestamps should lie within
    the range of the raw timestamps corresponding to recorded data.
    :param target_timestamps: Times at which box values will be interpolated, sorted in increasing order.
    :param box_timestamps: Times corresponding to each box in the box sequence, sorted in increasing order.
    :param boxes: Sequence of boxes at each timestamp corresponding to an actor's position over time, from the
        raw data. The first box corresponds to the current frame.
    :return: Sequence of Quaternion rotations at each timestamp corresponding to an actor's rotation over time, where
        rotation is interpolated at the target timestamps.
    """
    rotations = []
    for current_target_timestamp in target_timestamps:
        next_box_index = bisect_right(box_timestamps[:-1], current_target_timestamp)
        prev_box_index = next_box_index - 1
        assert prev_box_index >= 0
        tdiff_between_boxes = box_timestamps[next_box_index] - box_timestamps[prev_box_index]
        assert tdiff_between_boxes > 0.0
        target_tdiff_from_prev = current_target_timestamp - box_timestamps[prev_box_index]
        target_timestamp_relative_position = target_tdiff_from_prev / tdiff_between_boxes
        interpolated_box_rotation = Quaternion.slerp(q0=boxes[prev_box_index].orientation, q1=boxes[next_box_index].orientation, amount=target_timestamp_relative_position)
        rotations.append(interpolated_box_rotation)
    return rotations

def interpolate_coordinates(target_timestamps: Union[npt.NDArray[np.float64], List[float]], box_timestamps: Union[npt.NDArray[np.float64], List[float]], box_coordinates: List[Union[npt.NDArray[np.float64], Tuple[float, ...]]]) -> List[npt.NDArray[np.float64]]:
    """
    Given a sequence of boxes representing box positions over time along with their corresponding timestamps,
    interpolate the box coordinates at the target timestamps. Target timestamps should lie within
    the range of the raw timestamps corresponding to recorded data.
    :param target_timestamps: Times at which box coordinates will be interpolated, sorted in increasing order.
    :param box_timestamps: Times corresponding to each box coordinate in the box sequence, sorted in increasing order.
    :param box_coordinates: Sequence of box coordinates at each timestamp corresponding to an actor's position over
        time, from the raw data. The first box corresponds to the current frame.
    :return: Sequence of array coordinate positions in np.array(x, y, z) format at each timestamp corresponding to an
        actor's position over time, where position is interpolated at the target timestamps.
    """
    xs = list(np.interp(x=target_timestamps, xp=box_timestamps, fp=np.array([coordinate[0] for coordinate in box_coordinates])))
    ys = list(np.interp(x=target_timestamps, xp=box_timestamps, fp=np.array([coordinate[1] for coordinate in box_coordinates])))
    zs = list(np.interp(x=target_timestamps, xp=box_timestamps, fp=np.array([coordinate[2] for coordinate in box_coordinates])))
    centers = [np.array([x, y, z]) for x, y, z in zip(xs, ys, zs)]
    return centers

def pack_future_boxes(track_token_2_box_sequence: Dict[str, List[Box3D]], future_horizon_len_s: float, future_interval_s: float) -> List[Box3D]:
    """
    Given a mapping from all the track tokens to the list of corresponding boxes at each future
        timestamp, this function packs the "future" data into the individual Box3D boxes in the current Sample,
        such that each box contains its future center positions and future orientations in subsequent frames.
    :param track_token_2_box_sequence: Mapping from track token to list of corresponding boxes at each timestamp
        in the global coordinate frame, returned by function get_future_box_sequence()
    :param future_horizon_len_s: Timestamp horizon of the future waypoints in seconds.
    :param future_interval_s: Timestamp interval of the future waypoints in seconds.
    :return: List of boxes in a frame, where each box contains future center positions and future orientations in
        subsequent frames.
    """
    boxes_out: List[Box3D] = []
    for track_token, box_sequence in track_token_2_box_sequence.items():
        current_box = box_sequence[0]
        future_centers = [[box.center if box else (np.nan, np.nan, np.nan) for box in box_sequence[1:]]]
        future_orientations = [[box.orientation if box else None for box in box_sequence[1:]]]
        mode_probs = [1.0]
        box_with_future = Box3D(center=current_box.center, size=current_box.size, orientation=current_box.orientation, label=current_box.label, score=current_box.score, velocity=current_box.velocity, angular_velocity=current_box.angular_velocity, payload=current_box.payload, token=current_box.token, track_token=current_box.track_token, future_horizon_len_s=future_horizon_len_s, future_interval_s=future_interval_s, future_centers=future_centers, future_orientations=future_orientations, mode_probs=mode_probs)
        boxes_out.append(box_with_future)
    return boxes_out

def draw_line(canvas: Union[npt.NDArray[np.float64], Axes], from_x: int, to_x: int, from_y: int, to_y: int, color: Tuple[Union[int, float], Union[int, float], Union[int, float]], linewidth: float, marker: Optional[str]=None, alpha: float=1.0) -> None:
    """
    Draw a line on a matplotlib/cv2 canvas. Note that marker is not used in cv2.
    :param canvas: Canvas to draw.
    :param from_x: Start x position.
    :param to_x: End x position.
    :param from_y: Start y position.
    :param to_y: End y position.
    :param color: Color of the line.
    :param linewidth: Width of the line.
    :param marker: Marker to use, defaults to None
    :param alpha: Alpha channel of the color, defaults to 1.0
    """
    if isinstance(canvas, np.ndarray):
        color_int = tuple((int(c * 255) for c in color))
        cv2.line(canvas, (int(from_x), int(from_y)), (int(to_x), int(to_y)), color_int[::-1], linewidth)
    else:
        canvas.plot([from_x, to_x], [from_y, to_y], color=color, linewidth=linewidth, marker=marker, alpha=alpha)

def split_vehicles_by_size(boxes: List[Box3D], short_vehicles_id: int, long_vehicles_id: int) -> List[Box3D]:
    """
    This function splits vehicles into a different classes based on whether they are longer or shorter than 7m
    in length. It assigns labels to boxes
    :param boxes: List of boxes containing annotations of all types.
    :param short_vehicles_id: ID used in labelmap for short vehicles.
    :param long_vehicles_id: ID used in labelmap for long vehicles.
    :return: List of boxes where vehicles have been split into two classes and labeled accordingly.
    """
    final_boxes = []
    for box in boxes:
        if box.label == short_vehicles_id or box.label == long_vehicles_id:
            if box.length <= 7:
                box.label = short_vehicles_id
                final_boxes.append(box)
            if box.length > 7:
                box.label = long_vehicles_id
                final_boxes.append(box)
        else:
            final_boxes.append(box)
    return final_boxes

def crop_rect(img: npt.NDArray[np.float64], rect: Tuple[Tuple[float, float], Tuple[float, float], float]) -> npt.NDArray[np.float64]:
    """
    Crop a rectangle from a 2D image.
    :param img: Numpy array containing the image.
    :param rect: Rectangle defined by cv2.minAreaRect.
    :return: Cropped img.
    """
    fcenter = rect[0]
    fsize = rect[1]
    angle = rect[2]
    center, size = (tuple(map(int, fcenter)), tuple(map(int, fsize)))
    rect_diagonal_length = math.ceil(math.sqrt(size[0] ** 2 + size[1] ** 2))
    crop_size_before_rotate = (rect_diagonal_length, rect_diagonal_length)
    crop_before_rotate = cv2.getRectSubPix(img, crop_size_before_rotate, center)
    new_center = (rect_diagonal_length / 2, rect_diagonal_length / 2)
    M = cv2.getRotationMatrix2D(new_center, angle, 1)
    rotated_img: npt.NDArray[np.float64] = cv2.warpAffine(crop_before_rotate, M, crop_size_before_rotate)
    cropped_img: npt.NDArray[np.float64] = cv2.getRectSubPix(rotated_img, size, new_center)
    return cropped_img

def get_waypoints_for_agent(agent_box: LidarBox, end_timestamp: int) -> List[Waypoint]:
    """
    Extracts waypoints from a LidarBox by looking into the future samples
    :param agent_box: The first LidarBox
    :param end_timestamp: The maximal timestamp, used to stop extraction
    :return: Waypoints of the agent up to end_timestamp
    """
    agent_waypoints: List[Waypoint] = []
    tolerance_us = 60000
    while agent_box.timestamp <= end_timestamp + tolerance_us:
        agent_waypoints.append(_waypoint_from_lidar_box(agent_box))
        agent_box = agent_box.next
        if agent_box is None:
            break
    return agent_waypoints

def _get_logs(db: NuPlanDB, split2log: Dict[str, List[str]], split_name: str) -> List[Log]:
    """
    For all the given split `split_name`, convert its corresponding log names into Log objects.
    :param db: NuPlanDB.
    :param split2log: Mapping from a split name to its corresponding data. The data is given as a list of log names
        (example of log name: '2021.07.16.20.45.29_veh-35_01095_01486').
    :param split_name: The split in which we want to get the Log objects. (example of split_name: "val").
    :return: List of logs.
    """
    logs = []
    for log_name in split2log[split_name]:
        log = db.log.select_one(logfile=log_name)
        if log is not None:
            logs.append(log)
    return logs

def _get_samples_from_logs(logs: List[Log], broken_extractions: Set[str]) -> List[Sample]:
    """
    Returns all the non-broken samples of a list of logs.
    For definitions of 'sample' and 'extraction', please take a look at README.md.

    :param logs: List of logs from which to extract samples.
    :param broken_extractions: List of extractions whose samples should be excluded from the output of this function.
    :return: List of non-broken samples associated with the given logs.
    """
    samples = []
    for log in logs:
        for extraction in log.extractions:
            if extraction.token in broken_extractions:
                continue
            for sample in extraction.samples:
                samples.append(sample)
    return samples

def _set_splits_samples(split2samples: DefaultDict[str, List[Sample]], db: NuPlanDB, split2log: Dict[str, List[str]], broken_extractions: Optional[Set[str]]=None, sort_train: bool=True) -> None:
    """
    Populates split2samples with all the main splits and the ones defined in split2log, converting log names into
    the list of non-broken samples they contain in the database.

    :param split2samples: Main dictionary containing a mapping from split name to its corresponding data.
        The data is given as a list of samples.
    :param db: NuPlanDB.
    :param split2log: Mapping from a split name to its corresponding data. The data is given as a list of log names
        (example of log name: '2019.07.03.03.29.58_mvp-veh-8')
    :param broken_extractions: List of extractions whose samples should be excluded from the samples populated in
        `split2samples`.
    :param sort_train: Whether or not to sort the train split with respect to sample tokens. (This is useful
        to guarantee that randomly subsampled splits from train will not differ if they have the same random seed.)
    """
    broken_extractions = broken_extractions or set()
    for split_name in split2log.keys():
        logs = _get_logs(db, split2log, split_name)
        split2samples[split_name] = _get_samples_from_logs(logs, broken_extractions=broken_extractions)
    if 'val' in split2samples or 'test' in split2samples:
        split2samples['valtest'] = split2samples['val'] + split2samples['test']
    if 'train' not in split2samples:
        split2samples['train'] = [rec for rec in split2samples['all'] if rec not in split2samples['valtest']]
    if sort_train:
        split2samples['train'].sort(key=lambda sample: str(sample.token))

def _get_all_samples(db: NuPlanDB, vehicle_type: str, broken_extractions: Optional[Set[str]]=None, excluded_drive_log_tags: Optional[Set[str]]=None) -> List[Sample]:
    """
    Returns all non-broken samples associated with one vehicle.

    :param db: NuPlanDB.
    :param vehicle_type: name of the vehicle which we should get data from.
    :param broken_extractions: List of extractions whose samples should be excluded from the output of this function.
    :param excluded_drive_log_tags: Logs that have ANY of those drive log tags will be excluded.
    :return: List of non-broken samples associated with given vehicle_type.
    """
    broken_extractions = broken_extractions or set()
    excluded_drive_log_tags = excluded_drive_log_tags or set()
    logs = db.log.select_many(vehicle_type=vehicle_type)
    logs = [log for log in logs if not set(log.drive_log_tags).intersection(excluded_drive_log_tags)]
    return _get_samples_from_logs(logs, broken_extractions)

def _set_location_splits(split2samples: DefaultDict[str, List[Sample]], db: NuPlanDB, core_splits_names: List[str]) -> None:
    """
    Populates split2samples with splits by region and country done on top of core splits.

    For example:
        "train" -> "train", "train.United_States", "train.bs", , "train.lv", "train.ptc", "train.Singapore", "train.sg".

    :param split2samples: Main dictionary containing a mapping from split name to its corresponding data. The data is
     given as a list of samples. This function assumes core splits already exists (e.g. "train", "val, "test").
    :param db: NuPlanDB.
    :param core_splits_names: Split names on which the location splits should be done. (e.g. "train", "val, "test").
    """
    for split_name in core_splits_names:
        region_accumulator = []
        for region in db.regions:
            region_split_name = split_name + '.' + region
            country_split_name = split_name + '.' + db.country(region)
            split2samples[region_split_name] = [rec for rec in split2samples[split_name] if rec.extraction.log.location in db.locations(region)]
            if country_split_name not in split2samples:
                split2samples[country_split_name] = []
            split2samples[country_split_name] += split2samples[region_split_name]
            region_accumulator += split2samples[region_split_name]
        assert set(region_accumulator) == set(split2samples[split_name])

def _set_subsampled_splits(split2samples: DefaultDict[str, List[Sample]], db: NuPlanDB, core_splits_names: List[str], random_seed: Union[str, int], n_samples_per_region: int, split_suffix: str) -> None:
    """
    Populates split2samples with core splits.
    :param split2samples: Main dictionary containing a mapping from split name to its corresponding data. The data is
     given as a list of samples.
    :param db: NuPlanDB.
    :param core_splits_names: Name of the core splits, such as, ['test', 'val', 'valtest', 'train'].
    :param random_seed: Random seed to use for picking tokens.
    :param n_samples_per_region: number of samples for each region.
    :param split_suffix: suffix of the split name, such as 'mini', 'dev'.
    """
    st0 = random.getstate()
    random.seed(random_seed)
    for split_name in core_splits_names:
        for region in db.regions:
            temp = split2samples[split_name + '.' + region].copy()
            random.shuffle(temp)
            split2samples[split_name + '.' + split_suffix] += temp[:n_samples_per_region]
    random.setstate(st0)

def _convert_to_tokens(split2samples: DefaultDict[str, List[Sample]]) -> DefaultDict[str, List[str]]:
    """
    Convert all Samples provided into their corresponding tokens.

    :param split2samples: Main dictionary containing a mapping from split name to its corresponding data. The data is
     given as a list of samples.
    :return: Same mapping as split2samples except the data is in tokens format.
    """
    split2tokens = defaultdict(list)
    for split in split2samples:
        split2tokens[split] = [record.token for record in split2samples[split]]
    return split2tokens

class BaseNuPlanDBSplitter(DBSplitterInterface):
    """Base class for all NuPlanDB splitters."""

    def __init__(self, db: NuPlanDB):
        """
        :param db: NuPlanDB instance.
        """
        self._db = db
        self._db.add_ref()

    def __del__(self) -> None:
        """
        Called when the splitter is being destroyed.
        """
        self._db.remove_ref()

    def __repr__(self) -> str:
        """
        Get the string representation.
        :return: The string representation.
        """
        return "{}(NuPlanDB('{}'))".format(self.__class__.__name__, self._db.name)

    def list(self) -> List[str]:
        """
        Get the list of the splits.
        :return: The list of splits.
        """
        return list(self._splits.keys())

    def split(self, split_name: str) -> List[str]:
        """
        Get list of tokens for the split.
        :return: The list of tokens for the split.
        """
        return sorted(self._splits[split_name])

    def logs(self, split_name: str) -> List[str]:
        """
        Get list of logs for the split.
        :return: The list of logs for the split.
        """
        sample_tokens = self.split(split_name)
        return list({self._db.sample[token].extraction.log.logfile for token in sample_tokens})

    @property
    @abc.abstractmethod
    def _splits(self) -> DefaultDict[str, List[str]]:
        """
        Returns a dictionary that maps from split name to list of NuPlanDB tokens.
        :return: A dictionary that maps from split name to list of NuPlanDB tokens.
        """
        pass

def list(self) -> List[str]:
    """
        Get the list of the splits.
        :return: The list of splits.
        """
    return list(self._splits.keys())

def split(self, split_name: str) -> List[str]:
    """
        Get list of tokens for the split.
        :return: The list of tokens for the split.
        """
    return sorted(self._splits[split_name])

def discover_log_dbs(load_path: Union[List[str], str]) -> List[str]:
    """
    Discover all log dbs from the input load path.
    If the path is a filename, expand the path and return the list of filenames in that path.
    Else, if the path is already a list, expand each path in the list and return the flattened list.
    :param load_path: Load path, it can be a filename or list of filenames of a database and/or dirs of databases.
    :return: A list with all discovered log database filenames.
    """
    if isinstance(load_path, list):
        nested_db_filenames = [get_db_filenames_from_load_path(path) for path in sorted(load_path)]
        db_filenames = [filename for filenames in nested_db_filenames for filename in filenames]
    else:
        db_filenames = get_db_filenames_from_load_path(load_path)
    return db_filenames

def load_log_db_mapping(data_root: str, db_files: Optional[Union[List[str], str]], maps_db: GPKGMapsDB, max_workers: Optional[int]=None, verbose: bool=True) -> Dict[str, NuPlanDB]:
    """
    Load all log database objects and hash them based on their log name.
    Log databases will be discovered based on the input path and downloaded if needed.
    All discovered databases will be loaded/downloaded concurrently in multiple threads.
    :param data_root: Local data root for loading/storing the log databases.
                      If `db_files` is not None, all downloaded databases will be stored to this data root.
    :param db_files: Local/remote filename or list of filenames to be loaded.
                     If None, all database filenames found under `data_root` will be used.
    :param maps_db: Instantiated map database object to be passed to each log database.
    :param max_workers: Maximum number of workers to use when loading the databases concurrently.
                        Only used when the number of databases to load is larger than this parameter.
    :param verbose: Whether to print progress and details during the database loading process.
    :return: Mapping from log name to loaded log database object.
    """
    load_path = data_root if db_files is None else db_files
    db_filenames = discover_log_dbs(load_path)
    num_workers = min(len(db_filenames), MAX_DB_LOADING_THREADS)
    num_workers = num_workers if max_workers is None else min(num_workers, max_workers)
    with ThreadPoolExecutor(max_workers=num_workers) as executor:
        futures = [executor.submit(NuPlanDB, data_root, path, maps_db, verbose) for path in db_filenames]
        futures_iterable = as_completed(futures)
        wrapped_iterable = tqdm(futures_iterable, total=len(futures), leave=False) if verbose else futures_iterable
        log_dbs = [future.result() for future in wrapped_iterable]
    log_dbs = sorted(log_dbs, key=lambda log_db: str(log_db.log_name))
    log_db_mapping = {log_db.log_name: log_db for log_db in log_dbs}
    return log_db_mapping

class NuPlanDBWrapper:
    """Wrapper for NuPlanDB that allows loading and accessing mutliple log database."""

    def __init__(self, data_root: str, map_root: str, db_files: Optional[Union[List[str], str]], map_version: str, max_workers: Optional[int]=None, verbose: bool=True):
        """
        Initialize the database wrapper.
        :param data_root: Local data root for loading (or storing downloaded) the log databases.
                        If `db_files` is not None, all downloaded databases will be stored to this data root.
        :param map_root: Local map root for loading (or storing downloaded) the map database.
        :param db_files: Path to load the log databases from, which can be:
                         * filename path to single database:
                            - locally - e.g. /data/sets/nuplan/v1.0/log_1.db
                            - remotely (S3) - e.g. s3://bucket/nuplan/v1.0/log_1.db
                         * directory path of databases to load:
                            - locally - e.g. /data/sets/nuplan/v1.0/
                            - remotely (S3) - e.g. s3://bucket/nuplan/v1.0/
                         * list of database filenames:
                            - locally - e.g. [/data/sets/nuplan/v1.0/log_1.db, /data/sets/nuplan/v1.0/log_2.db]
                            - remotely (S3) - e.g. [s3://bucket/nuplan/v1.0/log_1.db, s3://bucket/nuplan/v1.0/log_2.db]
                         * list of database directories:
                            - locally - e.g. [/data/sets/nuplan/v1.0_split_1/, /data/sets/nuplan/v1.0_split_2/]
                            - remotely (S3) - e.g. [s3://bucket/nuplan/v1.0_split_1/, s3://bucket/nuplan/v1.0_split_2/]
                         Note: Regex expansion is not yet supported.
                         Note: If None, all database filenames found under `data_root` will be used.
        :param map_version: Version of map database to load. The map database is passed to each loaded log database.
        :param max_workers: Maximum number of workers to use when loading the databases concurrently.
                            Only used when the number of databases to load is larger than this parameter.
        :param verbose: Whether to print progress and details during the database loading process.
        """
        self._data_root = data_root
        self._map_root = map_root
        self._db_files = db_files
        self._map_version = map_version
        self._max_workers = max_workers
        self._verbose = verbose
        assert not self._data_root.startswith('s3://'), f'Data root cannot be an S3 path, got {self._data_root}'
        assert not self._map_root.startswith('s3://'), f'Map root cannot be an S3 path, got {self._map_root}'
        self._data_root = self._data_root.replace('//', '/')
        self._map_root = self._map_root.replace('//', '/')
        self._maps_db = GPKGMapsDB(map_root=self._map_root, map_version=self._map_version)
        logger.info('Loaded maps DB')
        self._log_db_mapping = load_log_db_mapping(data_root=self._data_root, db_files=self._db_files, maps_db=self._maps_db, max_workers=self._max_workers, verbose=self._verbose)
        logger.info(f'Loaded {len(self.log_dbs)} log DBs')

    def __reduce__(self) -> Tuple[Type[NuPlanDBWrapper], Tuple[Any, ...]]:
        """
        Hints on how to reconstruct the object when pickling.
        :return: Object type and constructor arguments to be used.
        """
        return (self.__class__, (self._data_root, self._map_root, self._db_files, self._map_version, self._max_workers, self._verbose))

    def __del__(self) -> None:
        """
        Called when the object is being garbage collected.
        """
        for log_name in self.log_names:
            self._log_db_mapping[log_name].remove_ref()

    @property
    def data_root(self) -> str:
        """Get the data root."""
        return self._data_root

    @property
    def map_root(self) -> str:
        """Get the map root."""
        return self._map_root

    @property
    def map_version(self) -> str:
        """Get the map version."""
        return self._map_version

    @property
    def maps_db(self) -> GPKGMapsDB:
        """Get the map database object."""
        return self._maps_db

    @property
    def log_db_mapping(self) -> Dict[str, NuPlanDB]:
        """Get the dictionary that maps log names to log database objects."""
        return self._log_db_mapping

    @property
    def log_names(self) -> List[str]:
        """Get the list of log names of all loaded log databases."""
        return list(self._log_db_mapping.keys())

    @property
    def log_dbs(self) -> List[NuPlanDB]:
        """Get the list of all loaded log databases."""
        return list(self._log_db_mapping.values())

    def get_log_db(self, log_name: str) -> NuPlanDB:
        """
        Retrieve a log database by log name.
        :param log_name: Log name to access the database hash table.
        :return: Retrieve database object.
        """
        return self._log_db_mapping[log_name]

    def get_all_scenes(self) -> Iterable[Scene]:
        """
        Retrieve and yield all scenes across all loaded log databases.
        :yield: Next scene from all scenes in the loaded databases.
        """
        for db in self._log_db_mapping.values():
            for scene in db.scene:
                yield scene

    def get_all_scenario_types(self) -> List[str]:
        """Retrieve all unique scenario tags in the collection of databases."""
        return sorted({tag for log_db in self.log_dbs for tag in log_db.get_unique_scenario_tags()})

@property
def log_names(self) -> List[str]:
    """Get the list of log names of all loaded log databases."""
    return list(self._log_db_mapping.keys())

@property
def log_dbs(self) -> List[NuPlanDB]:
    """Get the list of all loaded log databases."""
    return list(self._log_db_mapping.values())

def get_all_scenes(self) -> Iterable[Scene]:
    """
        Retrieve and yield all scenes across all loaded log databases.
        :yield: Next scene from all scenes in the loaded databases.
        """
    for db in self._log_db_mapping.values():
        for scene in db.scene:
            yield scene

def get_all_scenario_types(self) -> List[str]:
    """Retrieve all unique scenario tags in the collection of databases."""
    return sorted({tag for log_db in self.log_dbs for tag in log_db.get_unique_scenario_tags()})

