def read_nuboard_file_paths(file_paths: List[Path]) -> List[NuBoardFile]:
    """
    Read a list of file paths to NuBoardFile data class.
    :param file_paths: A list of file paths.
    :return A list of NuBoard files.
    """
    nuboard_files = []
    for file_path in file_paths:
        nuboard_file = NuBoardFile.load_nuboard_file(file_path)
        nuboard_file.current_path = file_path.parents[0]
        nuboard_files.append(nuboard_file)
    return nuboard_files

def _extract_metric_statistics_dict(metric_statistics_dataframe: MetricStatisticsDataFrame, planner_name: str, scenario_types: Optional[Tuple[str]]=None) -> Optional[Dict[str, HistogramStatistics]]:
    """
    Extract metric statistics dataframe and aggregate them into histogram data in a dictionary of
    {metric_statistics_name: HistogramStatistics}.
    :param metric_statistics_dataframe: Metric statistics dataframe.
    :param scenario_types: A tuple of scenario types to search from the metric statistics dataframe.
    :param planner_name: A planner name to search from the metric statistics dataframe.
    :return A dictionary of {metric_statistic_name: HistogramStatistics}.
    """
    histogram_statistics_dict = {}
    data_frame: pd.DataFrame = metric_statistics_dataframe.query_scenarios(scenario_types=scenario_types, planner_names=(planner_name,))
    if not len(data_frame):
        return None
    for statistic_name in metric_statistics_dataframe.statistic_names:
        columns = [f'{statistic_name}_stat_value', f'{statistic_name}_stat_unit', 'scenario_name', 'log_name']
        statistic_data_frame = data_frame[columns]
        values: npt.NDArray[np.float64] = np.asarray(statistic_data_frame.iloc[:, 0], dtype=np.float64)
        infinite_states = np.isinf(values)
        values[infinite_states] = np.nan
        scenarios: List[str] = list(np.asarray(statistic_data_frame.iloc[:, 2]))
        log_names: List[str] = list(np.asarray(statistic_data_frame.iloc[:, 3]))
        scenario_log_names: List[str] = []
        for scenario, log_name in zip(scenarios, log_names):
            scenario_log_names.append(scenario + ' (' + log_name + ')')
        if values.dtype != 'bool':
            values = np.round(values, HistogramTabFigureStyleConfig.decimal_places)
        unit = statistic_data_frame.iloc[0, 1] or 'value'
        histogram_statistics = HistogramStatistics(unit=unit, values=values, scenarios=scenario_log_names)
        histogram_statistics_dict[statistic_name] = histogram_statistics
    return histogram_statistics_dict

def _extract_scenario_score_type_histogram_statistics_dict(scenario_type_info: Dict[str, List[Tuple[float, str]]]) -> Dict[str, HistogramStatistics]:
    """
    Extract histogram statistics dict from a dictionary of {scenario_type_name: [(scenario_score, scenario_name)]}
    :param scenario_type_info: A dict of {scenario_type_name: [(scenario_score, scenario_name)]}
    :returns A dictionary of scenario type names and histogram statistics.
    """
    histogram_statistics_dict = {}
    for scenario_type_name, scenario_type_scores in scenario_type_info.items():
        values = np.round(np.asarray([score[0] for score in scenario_type_scores], dtype=np.float64), HistogramTabFigureStyleConfig.decimal_places)
        scenario_log_names = [score[1] for score in scenario_type_scores]
        histogram_statistics = HistogramStatistics(unit='scores', values=values, scenarios=scenario_log_names)
        histogram_statistics_dict[scenario_type_name] = histogram_statistics
    return histogram_statistics_dict

def _extract_metric_aggregator_scenario_type_score_data(metric_aggregator_dataframe: pd.DataFrame, scenario_types: List[str]) -> HistogramConstantConfig.HistogramScenarioTypeScoreStatisticType:
    """
    Extract scenario type scores from metric aggregator dataframe and transform it to a histogram form in a
    dictionary of {'planner_name': {'scenario_type': [scenario_score, scenario_name]}}.
    :param metric_aggregator_dataframe: Metric aggregator dataframe.
    :param scenario_types: List of selected scenario types.
    :return {'planner_name': {'scenario_type': [scenario_score, scenario_name]}}.
    """
    scenario_type_score_histogram_statistics_dict: HistogramConstantConfig.HistogramScenarioTypeScoreStatisticType = defaultdict(lambda: defaultdict(list))
    for _, row_data in metric_aggregator_dataframe.iterrows():
        num_scenarios = row_data['num_scenarios']
        if not np.isnan(num_scenarios):
            continue
        scenario_name = row_data['scenario'] + ' (' + row_data['log_name'] + ')'
        if 'all' in scenario_types:
            scenario_type_score_histogram_statistics_dict[row_data['planner_name']]['all'].append((row_data['score'], scenario_name))
        if 'all' in scenario_types or row_data['scenario_type'] in scenario_types:
            scenario_type_score_histogram_statistics_dict[row_data['planner_name']][row_data['scenario_type']].append((row_data['score'], scenario_name))
    return scenario_type_score_histogram_statistics_dict

def extract_scenario_score_type_score_histogram_data(histogram_file_name: str, metric_aggregator_dataframe_index: int, scenario_type_score_histogram_statistics_dict: HistogramConstantConfig.HistogramScenarioTypeScoreStatisticType) -> List[HistogramData]:
    """
    Get histogram data from scenario type score histogram statistics.
    :param histogram_file_name: Histogram file name.
    :param metric_aggregator_dataframe_index: Metric aggregator dataframe index.
    :param scenario_type_score_histogram_statistics_dict: Statistics dictionary with scenario types and their
    scores.
    :return Scenario type histogram data.
    """
    histogram_data_list: List[HistogramData] = []
    for planner_name, scenario_type_info in scenario_type_score_histogram_statistics_dict.items():
        histogram_statistics_dict = _extract_scenario_score_type_histogram_statistics_dict(scenario_type_info=scenario_type_info)
        histogram_data = HistogramData(experiment_index=metric_aggregator_dataframe_index, planner_name=planner_name, statistics=histogram_statistics_dict, histogram_file_name=histogram_file_name)
        histogram_data_list.append(histogram_data)
    return histogram_data_list

def aggregate_metric_statistics_dataframe_histogram_data(metric_statistics_dataframe: MetricStatisticsDataFrame, metric_statistics_dataframe_index: int, metric_choices: List[str], scenario_types: Optional[Tuple[str]]=None) -> Optional[List[HistogramData]]:
    """
    Aggregate metric statistics dataframe data for histograms.
    :param metric_statistics_dataframe: Metric statistics dataframe.
    :param metric_statistics_dataframe_index: Metric statistics dataframe index.
    :param metric_choices: List of selected metrics.
    :param scenario_types: List of selected scenario types.
    :return A dictionary of statistics and their statistic data.
    """
    histogram_data_list = []
    if len(metric_choices) and metric_statistics_dataframe.metric_statistic_name not in metric_choices:
        return None
    planner_names = metric_statistics_dataframe.planner_names
    for planner_name in planner_names:
        histogram_statistics_dict = _extract_metric_statistics_dict(metric_statistics_dataframe=metric_statistics_dataframe, scenario_types=scenario_types, planner_name=planner_name)
        if not histogram_statistics_dict:
            continue
        histogram_data_list.append(HistogramData(experiment_index=metric_statistics_dataframe_index, planner_name=planner_name, statistics=histogram_statistics_dict))
    return histogram_data_list

def compute_histogram_edges(bins: int, aggregated_data: Optional[HistogramConstantConfig.HistogramDataType]) -> HistogramConstantConfig.HistogramEdgesDataType:
    """
    Compute histogram edges across different planners in the same metric statistics.
    :param bins: Number of bins.
    :param aggregated_data: Histogram aggregated data.
    :return Histogram edge data.
    """
    histogram_edge_data: HistogramConstantConfig.HistogramEdgesDataType = {}
    if aggregated_data is None:
        return histogram_edge_data
    for metric_statistics_name, aggregated_histogram_data in aggregated_data.items():
        if metric_statistics_name not in histogram_edge_data:
            histogram_edge_data[metric_statistics_name] = {}
        edge_data: Dict[str, HistogramEdgeData] = {}
        for histogram_data in aggregated_histogram_data:
            for statistic_name, statistic in histogram_data.statistics.items():
                unit = statistic.unit
                if unit in ['bool', 'boolean']:
                    continue
                if statistic_name not in edge_data:
                    edge_data[statistic_name] = HistogramEdgeData(unit=unit, values=statistic.values)
                else:
                    edge_data[statistic_name].values = np.concatenate([edge_data[statistic_name].values, statistic.values])
        for statistic_name, statistic_edge_data in edge_data.items():
            unit = statistic_edge_data.unit
            if unit in ['count']:
                unique_values: npt.NDArray[np.float64] = np.unique(statistic_edge_data.values)
                histogram_edge_data[metric_statistics_name][statistic_name] = None if not len(unique_values) else unique_values
            else:
                finite_values = statistic_edge_data.values[~np.isnan(statistic_edge_data.values)]
                _, edges = np.histogram(finite_values, bins=bins)
                histogram_edge_data[metric_statistics_name][statistic_name] = None if not len(edges) else edges
    return histogram_edge_data

@dataclass(frozen=True)
class S3FileContent:
    """S3 file contents."""
    filename: Optional[str] = None
    last_modified: Optional[datetime] = None
    size: Optional[int] = None

    @property
    def date_string(self) -> Optional[str]:
        """Return date string format."""
        if not self.last_modified:
            return None
        return self.last_modified.strftime('%m/%d/%Y %H:%M:%S %Z')

    @property
    def last_modified_day(self) -> Optional[str]:
        """Return last modified day."""
        if not self.last_modified:
            return None
        datetime_now = datetime.now(timezone.utc)
        difference_day = (datetime_now - self.last_modified).days
        if difference_day == 0:
            return 'Less than 24 hours'
        elif difference_day < 30:
            return f'{difference_day} days ago'
        elif 30 <= difference_day < 60:
            return 'a month ago'
        else:
            return f'{difference_day / 30} months ago'

    def kb_size(self, decimals: int=2) -> Optional[float]:
        """
        Return file size in KB.
        :param decimals: Decimal points.
        """
        if not self.size:
            return None
        return float(np.round(self.size / 1024, decimals))

    def serialize(self) -> Dict[str, Any]:
        """
        Serialize the class.
        :return A dict of object variables.
        """
        return {'filename': self.filename, 'last_modified': str(self.last_modified), 'size': self.size}

    @classmethod
    def deserialize(cls, data: Dict[str, Any]) -> S3FileContent:
        """
        Deserialize data to s3 file content.
        :param data: A dictionary of data.
        :return S3FileContent after loaded the data.
        """
        return S3FileContent(filename=data['filename'], last_modified=datetime.fromisoformat(data['last_modified']), size=data['size'])

def kb_size(self, decimals: int=2) -> Optional[float]:
    """
        Return file size in KB.
        :param decimals: Decimal points.
        """
    if not self.size:
        return None
    return float(np.round(self.size / 1024, decimals))

@dataclass
class ExperimentFileData:
    """Data for experiment files."""
    file_paths: List[NuBoardFile]
    color_palettes: List[str] = field(default_factory=list)
    expert_color_palettes: List[str] = field(default_factory=list)
    available_metric_statistics_names: List[str] = field(default_factory=list)
    metric_statistics_dataframes: List[List[MetricStatisticsDataFrame]] = field(default_factory=list)
    metric_aggregator_dataframes: List[Dict[str, pd.DataFrame]] = field(default_factory=list)
    simulation_files: Dict[str, Any] = field(default_factory=dict)
    simulation_scenario_keys: List[SimulationScenarioKey] = field(default_factory=list)
    available_scenario_types: List[str] = field(default_factory=list)
    available_scenarios: Dict[str, Dict[str, List[str]]] = field(default_factory=dict)
    available_scenario_tokens: Dict[str, ScenarioTokenInfo] = field(default_factory=dict)
    file_path_colors: Dict[int, Dict[str, str]] = field(default_factory=dict)
    color_index: int = 0

    def __post_init__(self) -> None:
        """Post initialization."""
        if not self.simulation_files:
            self.simulation_files = defaultdict(set)
        if not self.available_scenario_tokens:
            self.available_scenario_tokens = defaultdict()
        if not self.color_palettes:
            self.color_palettes = Set1[9] + Set2[8] + Set3[12]
        if not self.expert_color_palettes:
            self.expert_color_palettes = Pastel2[8] + Pastel1[9] + Dark2[8]
        if not self.available_scenarios:
            self.available_scenarios = defaultdict(lambda: defaultdict(list))
        if self.file_paths:
            file_paths = self.file_paths
            self.file_paths = []
            self.update_data(file_paths=file_paths)

    def update_data(self, file_paths: List[NuBoardFile]) -> None:
        """
        Update experiment data with a new list of nuboard file paths.
        :param file_paths: A list of new nuboard file paths.
        """
        starting_file_path_index = len(self.file_paths)
        self._update_file_path_color(file_paths=file_paths, starting_file_path_index=starting_file_path_index)
        self._add_metric_files(file_paths=file_paths, starting_file_path_index=starting_file_path_index)
        self._add_metric_aggregator_files(file_paths=file_paths, starting_file_path_index=starting_file_path_index)
        self._add_simulation_files(file_paths=file_paths, starting_file_path_index=starting_file_path_index)
        self.file_paths += file_paths

    @staticmethod
    def _get_base_path(current_path: Path, base_path: Path, sub_folder: str) -> Path:
        """
        Get valid base path.
        :param current_path: Current nuboard file path.
        :Param base_path: Alternative base path.
        :param sub_folder: Sub folder.
        :return A base path.
        """
        default_path = base_path / sub_folder
        if current_path is None:
            return default_path
        base_folder = current_path / sub_folder
        if not base_folder.exists():
            base_folder = default_path
        return base_folder

    def _update_file_path_color(self, file_paths: List[NuBoardFile], starting_file_path_index: int) -> None:
        """
        Update file path colors.
        :param file_paths: A list of new nuboard file paths.
        :param starting_file_path_index: Starting file path index.
        """
        for index, file_path in enumerate(file_paths):
            file_path_index = starting_file_path_index + index
            self.file_path_colors[file_path_index] = defaultdict(str)
            metric_path = self._get_base_path(current_path=file_path.current_path, base_path=Path(file_path.metric_main_path), sub_folder=file_path.metric_folder)
            planner_names: List[str] = []
            if not metric_path.exists():
                continue
            for file in metric_path.iterdir():
                try:
                    data_frame = MetricStatisticsDataFrame.load_parquet(file)
                    planner_names += data_frame.planner_names
                except (FileNotFoundError, Exception) as e:
                    logger.info(e)
                    pass
            if not planner_names:
                simulation_path = self._get_base_path(current_path=file_path.current_path, base_path=Path(file_path.simulation_main_path), sub_folder=file_path.simulation_folder)
                if not simulation_path.exists():
                    continue
                planner_name_paths = simulation_path.iterdir()
                for planner_name_path in planner_name_paths:
                    planner_name = planner_name_path.name
                    planner_names.append(planner_name)
            planner_names = list(set(planner_names))
            for planner_name in planner_names:
                self.file_path_colors[file_path_index][planner_name] = self.color_palettes[self.color_index]
                self.color_index += 1

    def _add_metric_files(self, file_paths: List[NuBoardFile], starting_file_path_index: int) -> None:
        """
        Add and load metric files.
        Folder hierarchy: planner_name -> scenario_type -> metric result name -> scenario_name.pkl
        :param file_paths: A list of new nuboard files.
        :param starting_file_path_index: Starting file path index.
        """
        for index, file_path in enumerate(file_paths):
            file_path_index = starting_file_path_index + index
            self.metric_statistics_dataframes.append([])
            metric_path = self._get_base_path(current_path=file_path.current_path, base_path=Path(file_path.metric_main_path), sub_folder=file_path.metric_folder)
            if not metric_path.exists():
                continue
            for file in metric_path.iterdir():
                if file.is_dir():
                    continue
                try:
                    data_frame = MetricStatisticsDataFrame.load_parquet(file)
                    self.metric_statistics_dataframes[file_path_index].append(data_frame)
                    self.available_metric_statistics_names.append(data_frame.metric_statistic_name)
                except (FileNotFoundError, Exception):
                    pass
        self.available_metric_statistics_names = sorted(list(set(self.available_metric_statistics_names)), reverse=False)

    def _add_metric_aggregator_files(self, file_paths: List[NuBoardFile], starting_file_path_index: int) -> None:
        """
        Load metric aggregator files.
        :param file_paths: A list of new nuboard files.
        :param starting_file_path_index: Starting file path index.
        """
        for index, file_path in enumerate(file_paths):
            file_path_index = starting_file_path_index + index
            self.metric_aggregator_dataframes.append({})
            metric_aggregator_path = self._get_base_path(current_path=file_path.current_path, base_path=Path(file_path.metric_main_path), sub_folder=file_path.aggregator_metric_folder)
            if not metric_aggregator_path.exists():
                continue
            for file in metric_aggregator_path.iterdir():
                if file.is_dir():
                    continue
                try:
                    data_frame = pd.read_parquet(file)
                    self.metric_aggregator_dataframes[file_path_index][file.stem] = data_frame
                except (FileNotFoundError, Exception):
                    pass

    def _add_simulation_files(self, file_paths: List[NuBoardFile], starting_file_path_index: int) -> None:
        """
        Load simulation files.
        Folder hierarchy: planner_name -> scenario_type -> scenario_names -> iteration.pkl.
        :param file_paths: A list of new nuboard files.
        :param starting_file_path_index: Starting file path index.
        """
        for index, file_path in enumerate(file_paths):
            if file_path.simulation_folder is None:
                continue
            file_path_index = starting_file_path_index + index
            simulation_path = self._get_base_path(current_path=file_path.current_path, base_path=Path(file_path.simulation_main_path), sub_folder=file_path.simulation_folder)
            if not simulation_path.exists():
                continue
            planner_name_paths = simulation_path.iterdir()
            for planner_name_path in planner_name_paths:
                planner_name = planner_name_path.name
                scenario_type_paths = planner_name_path.iterdir()
                for scenario_type_path in scenario_type_paths:
                    log_name_paths = scenario_type_path.iterdir()
                    scenario_type = scenario_type_path.name
                    for log_name_path in log_name_paths:
                        scenario_name_paths = log_name_path.iterdir()
                        log_name = log_name_path.name
                        for scenario_name_path in scenario_name_paths:
                            scenario_name = scenario_name_path.name
                            scenario_key = f'{simulation_path.parents[0].name}/{planner_name}/{scenario_type}/{log_name}/{scenario_name}'
                            if scenario_key in self.simulation_files:
                                continue
                            files = scenario_name_path.iterdir()
                            for file in files:
                                self.simulation_files[scenario_key].add(file)
                            self.available_scenarios[scenario_type][log_name].append(scenario_name)
                            self.available_scenario_tokens[scenario_name] = ScenarioTokenInfo(scenario_name=scenario_name, scenario_token=scenario_name, scenario_type=scenario_type, log_name=log_name)
                            self.simulation_scenario_keys.append(SimulationScenarioKey(nuboard_file_index=file_path_index, log_name=log_name, planner_name=planner_name, scenario_type=scenario_type, scenario_name=scenario_name, files=list(self.simulation_files[scenario_key])))
        available_scenario_types = list(set(self.available_scenarios.keys()))
        self.available_scenario_types = sorted(available_scenario_types, reverse=False)

def __post_init__(self) -> None:
    """Post initialization."""
    if not self.simulation_files:
        self.simulation_files = defaultdict(set)
    if not self.available_scenario_tokens:
        self.available_scenario_tokens = defaultdict()
    if not self.color_palettes:
        self.color_palettes = Set1[9] + Set2[8] + Set3[12]
    if not self.expert_color_palettes:
        self.expert_color_palettes = Pastel2[8] + Pastel1[9] + Dark2[8]
    if not self.available_scenarios:
        self.available_scenarios = defaultdict(lambda: defaultdict(list))
    if self.file_paths:
        file_paths = self.file_paths
        self.file_paths = []
        self.update_data(file_paths=file_paths)

def update_data(self, file_paths: List[NuBoardFile]) -> None:
    """
        Update experiment data with a new list of nuboard file paths.
        :param file_paths: A list of new nuboard file paths.
        """
    starting_file_path_index = len(self.file_paths)
    self._update_file_path_color(file_paths=file_paths, starting_file_path_index=starting_file_path_index)
    self._add_metric_files(file_paths=file_paths, starting_file_path_index=starting_file_path_index)
    self._add_metric_aggregator_files(file_paths=file_paths, starting_file_path_index=starting_file_path_index)
    self._add_simulation_files(file_paths=file_paths, starting_file_path_index=starting_file_path_index)
    self.file_paths += file_paths

