        self.plot = main_figure.multi_polygons(xs='xs', ys='ys', fill_color=simulation_tile_agent_style['ego']['fill_color'], fill_alpha=simulation_tile_agent_style['ego']['fill_alpha'], line_color=simulation_tile_agent_style['ego']['line_color'], line_width=simulation_tile_agent_style['ego']['line_width'], source=data_sources)
